(async () => {
  try {
    const tc = window.TuquetCrawler;
    const startTime = Date.now();
    const initialQuotesCount = document.querySelectorAll('.quote').length;

    // Wait for dynamic hydration via MutationObserver quietness
    await tc.waitForDomIdle({ quietnessThresholdMs: 600, maxTimeoutMs: 6000 });

    const hydratedQuotesCount = document.querySelectorAll('.quote').length;
    const crawl = await tc.crawlDocument(document, {
      extractMetadata: true,
      extractMainContent: true,
      toMarkdown: true
    });

    const firstQuote = document.querySelector('.quote .text')?.textContent?.trim();
    const firstAuthor = document.querySelector('.quote .author')?.textContent?.trim();

    automaNextBlock({
      success: true,
      testName: 'SPA Dynamic Hydration',
      url: window.location.href,
      initialQuotesCount,
      hydratedQuotesCount,
      hydrationDetected: hydratedQuotesCount > 0 && initialQuotesCount === 0,
      firstQuoteSample: firstQuote ? `${firstQuote} — ${firstAuthor}` : null,
      markdownLength: crawl.markdown?.length || 0,
      executionMs: Date.now() - startTime
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
